// Default loads the embedded default catalog snapshot.
func Default() (*Catalog, error) {
	return Load(LoadOptions{})
}

// Load loads a catalog from an external manifest or falls back to the embedded snapshot.
func Load(opts LoadOptions) (*Catalog, error) {
	data := embeddedManifest
	source := "embedded"

	if opts.ManifestPath != "" {
		externalData, err := os.ReadFile(opts.ManifestPath)
		if err != nil {
			if opts.RequireExternal {
				return nil, fmt.Errorf("modelcatalog: read manifest %s: %w", opts.ManifestPath, err)
			}
		} else {
			data = externalData
			source = opts.ManifestPath
		}
	}

	return loadManifest(data, source)
}

func loadManifest(data []byte, source string) (*Catalog, error) {
	var m manifest
	if err := yaml.Unmarshal(data, &m); err != nil {
		return nil, fmt.Errorf("modelcatalog: parse manifest %s: %w", source, err)
	}
	if err := validateManifest(m); err != nil {
		return nil, fmt.Errorf("modelcatalog: validate manifest %s: %w", source, err)
	}
	return &Catalog{
		manifest:    m,
		manifestSrc: source,
	}, nil
}

func validateManifest(m manifest) error {
	if m.Version != maxSchemaVersion {
		return fmt.Errorf("manifest schema v%d required (got v%d); see ADR-009 for v0.11 schema redesign", maxSchemaVersion, m.Version)
	}
	if len(m.Policies) == 0 {
		return fmt.Errorf("policies must not be empty")
	}
	if _, ok := m.Policies["default"]; !ok {
		return fmt.Errorf("default policy must be defined")
	}

	policyNames := make([]string, 0, len(m.Policies))
	for name := range m.Policies {
		policyNames = append(policyNames, name)
	}
	sort.Strings(policyNames)
	for _, name := range policyNames {
		entry := m.Policies[name]
		if strings.TrimSpace(name) == "" {
			return fmt.Errorf("policy name must not be empty")
		}
		if entry.MinPower <= 0 {
			return fmt.Errorf("policy %q min_power must be > 0", name)
		}
		if entry.MaxPower <= 0 {
			return fmt.Errorf("policy %q max_power must be > 0", name)
		}
		if entry.MinPower > entry.MaxPower {
			return fmt.Errorf("policy %q min_power must be <= max_power", name)
		}
		if entry.MaxPower > 10 {
			return fmt.Errorf("policy %q max_power must be <= 10", name)
		}
		for _, requirement := range entry.Require {
			if !knownPolicyRequirement(requirement) {
				return fmt.Errorf("policy %q has unknown require invariant %q", name, requirement)
			}
		}

		return cat.AllConcreteModels(modelcatalog.SurfaceAgentOpenAI)
	}
	return nil
}

// modelReasoningWireMap returns a surface-system → surface-model-ID → reasoning_wire
// map sourced from the embedded catalog. Models without an explicit reasoning_wire
// field are omitted (the provider treats absence as the "provider" default).
//
// Keying by surface ID (e.g., "qwen/qwen3.6-27b") rather than catalog ID
// ("qwen3.6-27b") fixes the lookup mismatch: providers query by the model string
// they actually send on the wire, which is the surface ID, not the catalog key.
func modelReasoningWireMap() map[string]map[string]string {
	cat, err := modelcatalog.Default()
	if err != nil {
		return nil
	}
	all := cat.AllModels()
	if len(all) == 0 {
		return nil
	}
	out := make(map[string]map[string]string)
	for _, entry := range all {
		if entry.ReasoningWire == "" {
			continue
		}
		for surface, surfaceID := range entry.Surfaces {
			if out[surface] == nil {
				out[surface] = make(map[string]string)
			}
			out[surface][surfaceID] = entry.ReasoningWire
		}
	}
	return out
}

func rejectLegacyProviderReasoningKeys(data []byte) error {
	var raw struct {
		Providers map[string]map[string]any `yaml:"providers"`
	}
	if err := yaml.Unmarshal(data, &raw); err != nil {
		return err
	}
	for name, provider := range raw.Providers {
		if _, ok := provider["flavor"]; ok {
			return fmt.Errorf("provider %q: flavor is no longer supported; use a concrete provider type", name)
		}
		for _, key := range []string{"thinking" + "_level", "thinking" + "_budget"} {
			if _, ok := provider[key]; ok {
				return fmt.Errorf("provider %q: use reasoning instead of %s", name, key)
			}
		}
	}
	return nil
}

func (c *Config) finalize() error {
